"use client";

import { Timeline as TimelinePrimitive } from "@audio-ui/react";
import type { CSSProperties } from "react";
import { cn } from "@/lib/utils";

function Timeline({ className, ...props }: TimelinePrimitive.Root.Props) {
  return (
    <TimelinePrimitive.Root
      className={cn(
        "[--timeline-grid-color:color-mix(in_oklab,var(--border)_70%,transparent)] [--timeline-grid-accent-color:color-mix(in_oklab,var(--foreground)_16%,transparent)] flex w-full min-w-0 flex-col data-disabled:opacity-50",
        className
      )}
      data-slot="timeline"
      {...props}
    />
  );
}

type TimelineViewportProps = TimelinePrimitive.Viewport.Props & {
  /** `hidden` drops the native scrollbar, for a `TimelineNavigator` to scroll with instead. */
  scrollbar?: "hidden" | "native";
};

function TimelineViewport({
  className,
  scrollbar = "native",
  ...props
}: TimelineViewportProps) {
  return (
    <TimelinePrimitive.Viewport
      className={cn(
        "bg-background relative min-h-0 min-w-0 overscroll-x-contain",
        scrollbar === "hidden" &&
          "[scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
        className
      )}
      data-slot="timeline-viewport"
      {...props}
    />
  );
}

function TimelineRuler({ className, ...props }: TimelinePrimitive.Ruler.Props) {
  return (
    <TimelinePrimitive.Ruler
      className={cn(
        "h-7 border-b bg-background text-muted-foreground text-xs has-focus-visible:bg-muted shrink-0 cursor-pointer touch-none select-none",
        "data-disabled:pointer-events-none",
        className
      )}
      data-slot="timeline-ruler"
      {...props}
    />
  );
}

type TimelineLaneProps = Omit<TimelinePrimitive.Lane.Props, "style"> & {
  /** Distance between grid lines, in the timeline's units. Leave it out for no lines. */
  gridStep?: number;
  style?: CSSProperties;
};

/** A line every `gridStep` units, sized from the lane's own unit so it follows the zoom. */
function gridLines(gridStep: number | undefined): CSSProperties | undefined {
  if (!(gridStep && gridStep > 0)) {
    return;
  }
  return {
    backgroundImage:
      "repeating-linear-gradient(to right, var(--timeline-grid-color) 0 1px, transparent 1px 100%)",
    backgroundSize: `calc(var(--timeline-unit) * ${gridStep}) 100%`,
  };
}

function TimelineLane({
  className,
  gridStep,
  style,
  ...props
}: TimelineLaneProps) {
  return (
    <TimelinePrimitive.Lane
      className={cn("h-14 border-b bg-muted/30", className)}
      data-slot="timeline-lane"
      style={{ ...gridLines(gridStep), ...style }}
      {...props}
    />
  );
}

function TimelineMark({ className, ...props }: TimelinePrimitive.Mark.Props) {
  return (
    <TimelinePrimitive.Mark
      className={cn(
        "border-s ps-1.5 tabular-nums pointer-events-none inset-y-0 flex items-center",
        className
      )}
      data-slot="timeline-mark"
      {...props}
    />
  );
}

function TimelinePlayhead({
  className,
  ...props
}: TimelinePrimitive.Playhead.Props) {
  return (
    <TimelinePrimitive.Playhead
      className={cn(
        "bg-primary pointer-events-none inset-y-0 w-px",
        className
      )}
      data-slot="timeline-playhead"
      {...props}
    />
  );
}

function TimelineRange({ className, ...props }: TimelinePrimitive.Range.Props) {
  return (
    <TimelinePrimitive.Range
      className={cn(
        "rounded-none bg-primary/20 ring-1 ring-primary/50 ring-inset has-focus-visible:ring-2 has-focus-visible:ring-ring inset-y-0 cursor-grab touch-none data-dragging:cursor-grabbing data-disabled:cursor-not-allowed",
        className
      )}
      data-slot="timeline-range"
      {...props}
    />
  );
}

function TimelineRangeHandle({
  className,
  ...props
}: TimelinePrimitive.RangeHandle.Props) {
  return (
    <TimelinePrimitive.RangeHandle
      className={cn(
        "rounded-none bg-primary/60 hover:bg-primary has-focus-visible:bg-primary absolute inset-y-0 w-1.5 cursor-ew-resize data-[edge=end]:right-0 data-[edge=start]:left-0",
        "after:absolute after:-inset-x-1.5 after:inset-y-0 pointer-coarse:after:-inset-x-3",
        className
      )}
      data-slot="timeline-range-handle"
      {...props}
    />
  );
}

/** The whole timeline as one bar: drag the window to scroll, an edge to zoom, double-click to show everything. */
function TimelineNavigator({
  className,
  ...props
}: TimelinePrimitive.Navigator.Props) {
  return (
    <TimelinePrimitive.Navigator
      className={cn("h-5 rounded-none bg-muted shrink-0 select-none", className)}
      data-slot="timeline-navigator"
      {...props}
    >
      <TimelinePrimitive.NavigatorWindow
        aria-label="Visible range"
        className="min-w-6 rounded-none bg-primary/25 hover:bg-primary/35 has-focus-visible:ring-2 has-focus-visible:ring-ring/50 inset-y-0 cursor-grab active:cursor-grabbing"
      />
      <TimelinePrimitive.NavigatorHandle
        aria-label="Start of the visible range"
        className="rounded-none border border-ring bg-background has-focus-visible:ring-2 has-focus-visible:ring-ring/50 inset-y-0 w-2 cursor-ew-resize data-[edge=end]:-translate-x-full after:absolute after:-inset-x-1.5 after:inset-y-0"
        edge="start"
      />
      <TimelinePrimitive.NavigatorHandle
        aria-label="End of the visible range"
        className="rounded-none border border-ring bg-background has-focus-visible:ring-2 has-focus-visible:ring-ring/50 inset-y-0 w-2 cursor-ew-resize data-[edge=end]:-translate-x-full after:absolute after:-inset-x-1.5 after:inset-y-0"
        edge="end"
      />
    </TimelinePrimitive.Navigator>
  );
}

export {
  Timeline,
  TimelineLane,
  TimelineMark,
  TimelineNavigator,
  TimelinePlayhead,
  TimelineRange,
  TimelineRangeHandle,
  TimelineRuler,
  TimelineViewport,
};

"use client";

import { createSource } from "@audio-ui/react";
import { useCallback, useEffect, useState } from "react";
import { IconPlaceholder } from "@/app/(create)/components/icon-placeholder";
import { Button } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import {
  Timeline,
  TimelineLane,
  TimelineMark,
  TimelineNavigator,
  TimelinePlayhead,
  TimelineRange,
  TimelineRangeHandle,
  TimelineRuler,
  TimelineViewport,
} from "@/components/audio/elements/timeline";
import {
  barLabelInterval,
  DEFAULT_TEMPO,
  describeBarsBeats,
  gridInterval,
  secondsPerBar,
} from "@/lib/musical-time";

const BARS = 16;
const DURATION = BARS * secondsPerBar(DEFAULT_TEMPO);
const MIN_ZOOM = 8;
const MAX_ZOOM = 240;
const ZOOM_STEP = 1.5;
const LANES = ["drums", "bass"];

/** A transport clock as a source: the playhead follows it without re-rendering React. */
function usePlaybackClock() {
  const [clock] = useState(() => createSource(0));
  const [playing, setPlaying] = useState(false);

  useEffect(() => {
    if (!playing) {
      return;
    }
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      clock.set((clock.getSnapshot() + (now - last) / 1000) % DURATION);
      last = now;
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [clock, playing]);

  return { clock, playing, setPlaying };
}

const describePosition = (seconds: number) =>
  describeBarsBeats(seconds, DEFAULT_TEMPO);

export function TimelineDemo() {
  const { clock, playing, setPlaying } = usePlaybackClock();
  const [zoom, setZoom] = useState(32);
  const togglePlaying = useCallback(
    () => setPlaying((on) => !on),
    [setPlaying]
  );
  const zoomOut = useCallback(
    () => setZoom((z) => Math.max(MIN_ZOOM, z / ZOOM_STEP)),
    []
  );
  const zoomIn = useCallback(
    () => setZoom((z) => Math.min(MAX_ZOOM, z * ZOOM_STEP)),
    []
  );
  const seek = useCallback((seconds: number) => clock.set(seconds), [clock]);
  const [loop, setLoop] = useState<readonly [number, number]>([8, 16]);
  // The grid the lanes draw is the grid everything snaps to.
  const snapStep = gridInterval("adaptive", zoom, DEFAULT_TEMPO);
  const labelEvery = barLabelInterval(zoom, DEFAULT_TEMPO);
  const labels = Array.from(
    { length: Math.floor(DURATION / labelEvery) },
    (_, index) => index * labelEvery
  );

  return (
    <div className="flex w-full min-w-0 flex-col gap-3">
      <div className="flex items-center justify-between gap-2">
        <Button
          aria-label={playing ? "Pause" : "Play"}
          onClick={togglePlaying}
          size="icon"
          variant="outline"
        >
          <IconPlaceholder
            hugeicons={playing ? "PauseIcon" : "PlayIcon"}
            lucide={playing ? "PauseIcon" : "PlayIcon"}
            phosphor={playing ? "PauseIcon" : "PlayIcon"}
            remixicon={playing ? "RiPauseLine" : "RiPlayLine"}
            tabler={playing ? "IconPlayerPause" : "IconPlayerPlay"}
          />
        </Button>
        <ButtonGroup>
          <Button
            aria-label="Zoom out"
            disabled={zoom <= MIN_ZOOM}
            onClick={zoomOut}
            size="icon"
            variant="outline"
          >
            <IconPlaceholder
              hugeicons="ZoomOutAreaIcon"
              lucide="ZoomOutIcon"
              phosphor="MagnifyingGlassMinusIcon"
              remixicon="RiZoomOutLine"
              tabler="IconZoomOut"
            />
          </Button>
          <Button
            aria-label="Zoom in"
            disabled={zoom >= MAX_ZOOM}
            onClick={zoomIn}
            size="icon"
            variant="outline"
          >
            <IconPlaceholder
              hugeicons="ZoomInAreaIcon"
              lucide="ZoomInIcon"
              phosphor="MagnifyingGlassPlusIcon"
              remixicon="RiZoomInLine"
              tabler="IconZoomIn"
            />
          </Button>
        </ButtonGroup>
      </div>
      <Timeline
        className="gap-2"
        duration={DURATION}
        maxZoom={MAX_ZOOM}
        minZoom={MIN_ZOOM}
        onPositionChange={seek}
        onZoomChange={setZoom}
        snapStep={snapStep}
        source={clock}
        zoom={zoom}
      >
        <TimelineViewport className="rounded-lg border" scrollbar="hidden">
          <TimelineRuler
            aria-label="Playhead"
            getAriaValueText={describePosition}
          >
            {labels.map((seconds) => (
              <TimelineMark key={seconds} value={seconds}>
                {seconds / secondsPerBar(DEFAULT_TEMPO) + 1}
              </TimelineMark>
            ))}
            <TimelinePlayhead />
          </TimelineRuler>
          <TimelineLane className="h-4 cursor-cell">
            <TimelineRange
              aria-label="Loop"
              drawable
              getAriaValueText={describePosition}
              onValueChange={setLoop}
              value={loop}
            >
              <TimelineRangeHandle aria-label="Loop start" edge="start" />
              <TimelineRangeHandle aria-label="Loop end" edge="end" />
            </TimelineRange>
            <TimelinePlayhead />
          </TimelineLane>
          {LANES.map((name) => (
            <TimelineLane gridStep={snapStep} key={name}>
              <TimelinePlayhead />
            </TimelineLane>
          ))}
        </TimelineViewport>
        <TimelineNavigator getAriaValueText={describePosition} />
      </Timeline>
      <p className="text-muted-foreground text-xs">
        Cmd/Ctrl + scroll to zoom around the pointer, or drag the bar below.
        Drag across the strip under the ruler to set a loop. Hold Cmd/Ctrl to
        leave the grid, Shift to scrub finely.
      </p>
    </div>
  );
}
